/* ---------- France régionale (2/2) : Sud-Ouest, Occitanie, Provence, Savoie — puis Portugal ---------- */
const D41 = [
{ id:'gateau-basque', c:'eu', lat:43.360, lon:-1.402, base:8, prep:45, cook:40, diff:2, tags:['sweet','bake','fruit'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ead4',style:'cake',food:['#e0b45a','#8f1a3a','#f2dfa8','#c98a2c'],garnish:'#c9754a'},
  n:{fr:'Gâteau basque',en:'Gâteau basque'},
  p:{fr:'Cambo-les-Bains, Pays basque, France',en:'Cambo-les-Bains, Basque Country, France'},
  d:{fr:"Une pâte sablée épaisse renfermant soit une crème pâtissière, soit une confiture de cerises noires d'Itxassou. Les deux camps ne s'entendent pas, et chaque village tient la sienne pour la seule authentique.",
     en:"A thick shortcrust enclosing either pastry cream or black cherry jam from Itxassou. The two camps do not agree, and every village holds its own version to be the only authentic one."},
  i:[['flour',400,'g'],['butter',250,'g'],['sugar',250,'g'],['egg',4,'pc'],['egg_yolk',3,'pc'],['whole_milk',400,'ml'],['cornstarch',40,'g'],['morello_cherries',300,'g'],['dark_rum',2,'tbsp'],['almonds',60,'g'],['baking_powder',1,'tsp'],['vanilla',1,'tsp'],['salt',null,'']],
  s:{fr:["Travaillez le beurre pommade avec 200 g de sucre, ajoutez deux œufs, puis la farine, la poudre d'amandes et la levure.","Rassemblez sans pétrir, filmez et laissez reposer 3 heures au froid : cette pâte est molle et ne se travaille bien que glacée.","Faites une crème pâtissière avec le lait, les jaunes, le reste de sucre et la fécule ; parfumez au rhum et laissez refroidir.","Étalez deux tiers de la pâte dans un moule à bords hauts, garnissez de crème — ou de confiture de cerises — sans aller jusqu'au bord.","Couvrez du reste de pâte, soudez, dorez à l'œuf et rayez à la fourchette. Enfournez 40 minutes à 180 °C."],
     en:["Cream the softened butter with 200 g of sugar, add two eggs, then the flour, ground almonds and baking powder.","Bring together without kneading, wrap and rest for 3 hours in the fridge: this dough is soft and only handles well when cold.","Make a pastry cream with the milk, yolks, remaining sugar and cornstarch; flavour with rum and cool it.","Line a deep tin with two thirds of the dough and fill with the cream — or cherry jam — stopping short of the edge.","Cover with the remaining dough, seal, glaze with egg and score with a fork. Bake for 40 minutes at 180°C."]} },

{ id:'tourtiere-landaise', c:'eu', lat:43.890, lon:-0.500, base:8, prep:90, cook:30, diff:3, tags:['sweet','bake','fruit'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'pastry',food:['#f2dfa8','#e0b45a','#f4f0e6','#c98a2c'],garnish:'#c9754a'},
  n:{fr:'Tourtière landaise',en:'Landes tourtière'},
  p:{fr:'Mont-de-Marsan, Landes, France',en:'Mont-de-Marsan, Landes, France'},
  d:{fr:"Des feuilles de pâte étirées à la main jusqu'à la transparence, beurrées, froissées et empilées sur des pommes à l'armagnac. À la coupe, elle s'effondre en mille éclats — c'est le signe qu'elle est réussie.",
     en:"Sheets of dough stretched by hand until translucent, buttered, crumpled and piled over apples in armagnac. Cut into, it collapses into a thousand shards — the sign of a successful one."},
  i:[['flour',300,'g'],['warm_water',150,'ml'],['olive_oil',40,'ml'],['apple',1,'kg'],['sugar',180,'g'],['butter',200,'g'],['armagnac',80,'ml'],['orange_blossom_water',1,'tbsp'],['vanilla',1,'tsp'],['powdered_sugar',40,'g'],['salt',null,'']],
  s:{fr:["Pétrissez farine, eau tiède, huile et sel 20 minutes, jusqu'à obtenir une pâte très élastique ; huilez-la et laissez reposer 2 heures.","Faites revenir les pommes en lamelles avec 100 g de sucre, flambez à l'armagnac et laissez refroidir.","Étirez la pâte à la main sur une grande nappe farinée, en partant du centre, jusqu'à voir le tissu au travers.","Badigeonnez généreusement de beurre fondu et découpez des carrés larges.","Alternez dans un moule couches de pâte froissée et pommes, terminez par trois couches froissées, sucrez et enfournez 30 minutes à 190 °C."],
     en:["Knead flour, warm water, oil and salt for 20 minutes into a very elastic dough; oil it and rest for 2 hours.","Fry the sliced apples with 100 g of sugar, flame with armagnac and let them cool.","Stretch the dough by hand over a large floured cloth, working from the centre, until you can see the weave through it.","Brush generously with melted butter and cut into wide squares.","Layer crumpled pastry and apples in a tin, finish with three crumpled layers, sugar them and bake for 30 minutes at 190°C."]} },

{ id:'millas', c:'eu', lat:43.604, lon:1.444, base:6, prep:20, cook:60, diff:1, tags:['sweet','comfort','fry'],
  art:{v:'plate',bg:'#33301f',plate:'#f4ead4',style:'cake',food:['#e8c46a','#f2e0a8','#c9a24a','#f4f0e6'],garnish:'#c9754a'},
  n:{fr:'Millas',en:'Millas'},
  p:{fr:'Toulouse, Occitanie, France',en:'Toulouse, Occitania, France'},
  d:{fr:"Une bouillie de maïs refroidie en plaque, découpée en losanges et frite au beurre, sucrée à la sortie. Salée, elle accompagnait le confit ; sucrée, elle est devenue le goûter des enfants du Sud-Ouest.",
     en:"A maize porridge set in a slab, cut into diamonds and fried in butter, sugared as it comes out. Savoury, it accompanied confit; sweetened, it became the after-school treat of the South-West."},
  i:[['cornmeal',250,'g'],['whole_milk',1,'l'],['water',500,'ml'],['sugar',120,'g'],['salted_butter',150,'g'],['lemon_zest',1,'pc'],['orange_blossom_water',1,'tbsp'],['egg',2,'pc'],['salt',null,'']],
  s:{fr:["Portez le lait, l'eau, le zeste et une pincée de sel à frémissement.","Versez la farine de maïs en pluie fine en fouettant sans arrêt pour éviter les grumeaux.","Remuez à la cuillère de bois 40 minutes à feu doux : la masse doit se détacher des parois.","Hors du feu, incorporez les œufs, 50 g de beurre et la fleur d'oranger, puis étalez sur 2 cm dans un plat mouillé. Laissez prendre une nuit.","Découpez en losanges, faites-les dorer au beurre salé 4 minutes par face et sucrez généreusement à la sortie de la poêle."],
     en:["Bring the milk, water, zest and a pinch of salt to a simmer.","Rain in the cornmeal, whisking constantly to avoid lumps.","Stir with a wooden spoon for 40 minutes over low heat: the mass should pull away from the sides.","Off the heat, work in the eggs, 50 g of butter and the orange blossom water, then spread 2 cm deep in a dampened dish. Set overnight.","Cut into diamonds, fry them in salted butter 4 minutes a side and sugar them generously as they leave the pan."]} },

{ id:'gardiane-de-taureau', c:'eu', lat:43.566, lon:4.192, base:6, prep:40, cook:180, diff:2, tags:['beef','slow','sunday'],
  art:{v:'pot',bg:'#2b2419',plate:'#f0e4c8',style:'stew',food:['#6f2a2a','#8f3b2a','#c9a878','#e0913a'],garnish:'#7fae6a'},
  n:{fr:'Gardiane de taureau',en:'Camargue bull stew'},
  p:{fr:'Aigues-Mortes, Camargue, France',en:'Aigues-Mortes, Camargue, France'},
  d:{fr:"La viande de taureau de Camargue mijotée au vin rouge avec des olives noires et du zeste d'orange, servie sur du riz de Camargue. Le plat des gardians, ces gardiens de troupeaux à cheval des marais du delta.",
     en:"Camargue bull meat stewed in red wine with black olives and orange peel, served over Camargue rice. The dish of the gardians, the mounted herdsmen of the delta marshes."},
  i:[['beef_chuck',1.5,'kg'],['red_wine',1,'l'],['onion',3,'pc'],['carrot',3,'pc'],['garlic',8,'clove'],['black_olives',150,'g'],['orange_zest',2,'pc'],['smoked_bacon',150,'g'],['flour',3,'tbsp'],['olive_oil',80,'ml'],['thyme',4,'sprig'],['bay_leaf',3,'pc'],['juniper_berries',8,'pc'],['long_grain_rice',400,'g'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites mariner la viande en gros cubes 24 heures dans le vin rouge avec les légumes, le zeste d'orange et les aromates.","Égouttez, épongez soigneusement, puis saisissez la viande dans l'huile très chaude, par petites quantités.","Faites revenir les lardons et les légumes de la marinade, singez à la farine.","Versez la marinade portée à ébullition, ajoutez le genièvre, et laissez mijoter 3 heures à feu très doux.","Ajoutez les olives dénoyautées la dernière demi-heure. Servez sur du riz de Camargue nature."],
     en:["Marinate the meat in large cubes for 24 hours in the red wine with the vegetables, orange peel and aromatics.","Drain, dry thoroughly, then sear the meat in very hot oil, in small batches.","Fry the lardons and the marinade vegetables, then dust with flour.","Pour in the marinade brought to the boil, add the juniper, and simmer for 3 hours over very low heat.","Add the stoned olives for the last half hour. Serve over plain Camargue rice."]} },

{ id:'petits-pates-de-pezenas', c:'eu', lat:43.461, lon:3.423, base:8, prep:60, cook:35, diff:2, tags:['lamb','bake','street'],
  art:{v:'board',bg:'#33291f',plate:'#f2e6c8',style:'pastry',food:['#e0b45a','#c98a2c','#8f5a3a','#f2dfa8'],garnish:'#7fae6a'},
  n:{fr:'Petits pâtés de Pézenas',en:'Pézenas little pies'},
  p:{fr:'Pézenas, Languedoc, France',en:'Pézenas, Languedoc, France'},
  d:{fr:"De petits cylindres de pâte fourrés de mouton et de sucre, sucrés-salés comme une recette médiévale. Ils viendraient des cuisiniers indiens de lord Clive de l'Inde, qui séjourna à Pézenas en 1768.",
     en:"Small cylinders of pastry filled with mutton and sugar, sweet and savoury like a medieval recipe. They are said to come from the Indian cooks of Lord Clive of India, who stayed at Pézenas in 1768."},
  i:[['flour',400,'g'],['butter',200,'g'],['egg',2,'pc'],['ice_water',80,'ml'],['mutton_shoulder',400,'g'],['lamb_fat',80,'g'],['brown_sugar',80,'g'],['lemon_zest',2,'pc'],['nutmeg',1,'tsp'],['cinnamon',1,'tsp'],['dark_rum',2,'tbsp'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Sablez la farine et le beurre froid, liez d'un œuf et d'un peu d'eau glacée, et réservez une heure au froid.","Hachez le mouton et le gras au couteau, en petits dés, puis mêlez au sucre roux, au zeste, aux épices et au rhum.","Laissez la farce reposer une nuit : le sucre doit s'y fondre entièrement.","Découpez des bandes de pâte, formez de petits cylindres de 5 cm de haut, garnissez et fermez par un disque de pâte plissé.","Dorez à l'œuf et enfournez 35 minutes à 190 °C. Se mangent tièdes, jamais brûlants."],
     en:["Rub the cold butter into the flour, bind with an egg and a little iced water, and chill for an hour.","Chop the mutton and fat by knife into small dice, then mix with the brown sugar, zest, spices and rum.","Rest the filling overnight: the sugar must dissolve into it completely.","Cut strips of pastry, form small cylinders 5 cm high, fill them and close with a pleated disc of dough.","Glaze with egg and bake for 35 minutes at 190°C. Eaten warm, never scalding."]} },

{ id:'bourride', c:'eu', lat:43.405, lon:5.048, base:6, prep:35, cook:35, diff:2, tags:['sea','soup','sunday'],
  art:{v:'pot',bg:'#33301f',plate:'#f4ecd8',style:'fish',food:['#f0e0a8','#f4f0e6','#e8c46a','#7fae5a'],garnish:'#6fbf8f'},
  n:{fr:'Bourride',en:'Bourride'},
  p:{fr:'Martigues, Provence, France',en:'Martigues, Provence, France'},
  d:{fr:"La sœur blanche de la bouillabaisse : le bouillon de poisson y est lié à l'aïoli, hors du feu, jusqu'à devenir une crème onctueuse. Toute la difficulté tient là — un degré de trop et la sauce tourne.",
     en:"The white sister of bouillabaisse: the fish broth is bound with aioli off the heat until it becomes a silky cream. The whole difficulty is there — one degree too hot and the sauce splits."},
  i:[['monkfish',1.2,'kg'],['whitefish',600,'g'],['leek',2,'pc'],['fennel',1,'pc'],['onion',2,'pc'],['garlic',10,'clove'],['egg_yolk',5,'pc'],['olive_oil',350,'ml'],['white_wine',250,'ml'],['orange_zest',1,'pc'],['potato',800,'g'],['rustic_bread',8,'slice'],['saffron',1,'pinch'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites un fumet avec les parures, le poireau, le fenouil, l'oignon, le vin blanc et le zeste d'orange, 25 minutes ; filtrez.","Montez un aïoli au mortier : ail écrasé au sel, trois jaunes, puis l'huile en filet jusqu'à obtenir une pâte ferme.","Pochez les tronçons de poisson 10 minutes dans le fumet frémissant, puis retirez-les et gardez-les au chaud.","Délayez la moitié de l'aïoli avec deux jaunes, puis versez dessus une louche de fumet chaud en fouettant.","Reversez le tout dans la casserole hors du feu et remuez sans arrêt jusqu'à épaississement, sans jamais dépasser 80 °C."],
     en:["Make a stock with the trimmings, leek, fennel, onion, white wine and orange peel for 25 minutes; strain it.","Mount an aioli in a mortar: garlic crushed with salt, three yolks, then oil in a thread until firm.","Poach the fish sections for 10 minutes in the simmering stock, then lift them out and keep them warm.","Slacken half the aioli with two yolks, then pour a ladle of hot stock over it, whisking.","Return everything to the pan off the heat and stir constantly until it thickens, never exceeding 80°C."]} },

{ id:'pieds-et-paquets', c:'eu', lat:44.196, lon:5.945, base:6, prep:60, cook:300, diff:3, tags:['slow','comfort','sunday'],
  art:{v:'pot',bg:'#33251c',plate:'#f0e4c8',style:'stew',food:['#c9604a','#8f3b2a','#e8dcb8','#e0913a'],garnish:'#7fae6a'},
  n:{fr:'Pieds et paquets',en:'Pieds et paquets'},
  p:{fr:'Sisteron, Provence, France',en:'Sisteron, Provence, France'},
  d:{fr:"Des tripes d'agneau farcies au lard et à l'ail, ficelées en petits paquets et mijotées huit heures avec des pieds de mouton. Un plat de patience absolue, que l'on prépare la veille pour le dimanche.",
     en:"Lamb tripe stuffed with bacon and garlic, tied into small parcels and stewed for eight hours with sheep's trotters. A dish of absolute patience, prepared the day before for Sunday."},
  i:[['beef_tripe',1.2,'kg'],['veal_foot',4,'pc'],['smoked_bacon',250,'g'],['garlic',10,'clove'],['parsley',1,'bunch'],['onion',3,'pc'],['carrot',3,'pc'],['white_wine',500,'ml'],['ripe_tomato',500,'g'],['orange_zest',1,'pc'],['bay_leaf',3,'pc'],['thyme',4,'sprig'],['olive_oil',80,'ml'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites blanchir les tripes 15 minutes, rincez-les et découpez-les en carrés de 10 cm.","Mêlez le lard haché, l'ail et le persil ; déposez une cuillerée sur chaque carré et repliez en paquet.","Fixez chaque paquet en pratiquant une fente dans la tripe et en y passant le coin opposé — jamais de ficelle, la tradition l'interdit.","Rangez paquets et pieds serrés dans une cocotte avec oignon, carotte, tomate, vin blanc, zeste et aromates.","Couvrez d'eau à hauteur, portez à frémissement et laissez cuire 8 heures à 120 °C. Servez le lendemain, réchauffé."],
     en:["Blanch the tripe for 15 minutes, rinse it and cut it into 10 cm squares.","Mix the chopped bacon, garlic and parsley; place a spoonful on each square and fold into a parcel.","Fasten each parcel by cutting a slit in the tripe and threading the opposite corner through — never string, tradition forbids it.","Pack the parcels and trotters tightly in a pot with onion, carrot, tomato, white wine, zest and aromatics.","Cover with water, bring to a bare simmer and cook for 8 hours at 120°C. Serve the next day, reheated."]} },

{ id:'tourte-de-blettes', c:'eu', lat:43.775, lon:7.503, base:8, prep:60, cook:45, diff:2, tags:['sweet','veg','bake'],
  art:{v:'plate',bg:'#28331f',plate:'#f4ead4',style:'pastry',food:['#4f6f3a','#e0b45a','#f2dfa8','#8f1a3a'],garnish:'#7fae6a'},
  n:{fr:'Tourte de blettes',en:'Swiss chard pie'},
  p:{fr:'Menton, Côte d’Azur, France',en:'Menton, French Riviera, France'},
  d:{fr:"Une tourte sucrée aux feuilles de blettes, aux pommes, aux pignons et aux raisins secs. Le légume disparaît sous le sucre et ne laisse qu'une fraîcheur végétale : personne ne devine, et c'est tout l'intérêt.",
     en:"A sweet pie of chard leaves, apple, pine nuts and raisins. The vegetable vanishes under the sugar and leaves only a green freshness: nobody guesses, and that is the whole point."},
  i:[['flour',400,'g'],['butter',200,'g'],['sugar',200,'g'],['egg',3,'pc'],['collard_greens',800,'g'],['apple',3,'pc'],['pine_nuts',80,'g'],['raisins',80,'g'],['parmesan',60,'g'],['dark_rum',3,'tbsp'],['lemon_zest',1,'pc'],['powdered_sugar',40,'g'],['salt',null,'']],
  s:{fr:["Sablez la farine, le beurre et 80 g de sucre, liez d'un œuf et laissez reposer une heure au froid.","Retirez les côtes des blettes et ne gardez que le vert ; ciselez-le finement et salez-le 20 minutes pour le faire dégorger.","Pressez-le à pleines mains, puis mêlez-le aux pommes râpées, aux pignons, aux raisins au rhum, au sucre restant, au zeste et au parmesan.","Foncez un moule, garnissez, couvrez d'une abaisse et soudez les bords en les pinçant.","Enfournez 45 minutes à 180 °C, laissez refroidir complètement et poudrez de sucre glace. Se mange froide."],
     en:["Rub together the flour, butter and 80 g of sugar, bind with an egg and rest for an hour in the fridge.","Strip the ribs from the chard and keep only the green; shred it finely and salt it for 20 minutes to draw out water.","Squeeze it dry by the handful, then mix with the grated apple, pine nuts, rum-soaked raisins, remaining sugar, zest and parmesan.","Line a tin, fill it, cover with a lid of pastry and seal the edges by crimping.","Bake for 45 minutes at 180°C, cool completely and dust with icing sugar. Eaten cold."]} },

{ id:'crozets-au-beaufort', c:'eu', lat:45.618, lon:6.769, base:4, prep:20, cook:35, diff:1, tags:['cheese','comfort','veg'],
  art:{v:'pot',bg:'#33301f',plate:'#f0e2c0',style:'noodle',food:['#e0b45a','#f2dfa8','#c98a2c','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Crozets au beaufort',en:'Crozets with beaufort'},
  p:{fr:'Bourg-Saint-Maurice, Savoie, France',en:'Bourg-Saint-Maurice, Savoie, France'},
  d:{fr:"De minuscules carrés de pâte au sarrasin, gratinés au beaufort et aux diots. Le mot vient du savoyard croé, croix : on les découpait autrefois au couteau, un à un, sur la table de la ferme.",
     en:"Tiny squares of buckwheat pasta, baked under beaufort with local sausage. The name comes from the Savoyard croé, cross: they were once cut one by one with a knife on the farmhouse table."},
  i:[['buckwheat_flour',200,'g'],['flour',150,'g'],['egg',3,'pc'],['beaufort_cheese',300,'g'],['smoked_bacon',200,'g'],['onion',2,'pc'],['heavy_cream',300,'ml'],['white_wine',150,'ml'],['butter',60,'g'],['nutmeg',1,'pinch'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Pétrissez les farines et les œufs en une pâte dure, laissez-la reposer une heure, puis étalez-la très finement.","Détaillez des carrés de 5 mm de côté — c'est long, mais c'est ce qui fait le crozet.","Faites rissoler lardons et oignons dans le beurre, déglacez au vin blanc et laissez réduire.","Cuisez les crozets 12 minutes à l'eau bouillante salée : ils restent fermes.","Mêlez le tout à la crème et aux deux tiers du beaufort, versez dans un plat, couvrez du reste et gratinez 15 minutes à 200 °C."],
     en:["Knead the flours and eggs into a hard dough, rest it for an hour, then roll it very thin.","Cut 5 mm squares — it takes time, but that is what makes a crozet.","Fry the lardons and onions in the butter, deglaze with white wine and reduce.","Cook the crozets for 12 minutes in boiling salted water: they stay firm.","Toss everything with the cream and two thirds of the beaufort, tip into a dish, cover with the rest and brown for 15 minutes at 200°C."]} },

{ id:'farcon-savoyard', c:'eu', lat:45.857, lon:6.617, base:6, prep:40, cook:240, diff:2, tags:['veg','slow','festive'],
  art:{v:'pot',bg:'#33291f',plate:'#f0e4c8',style:'cake',food:['#c9924a','#e0b45a','#8f6a4a','#f2dfa8'],garnish:'#7fae6a'},
  n:{fr:'Farçon savoyard',en:'Savoyard farçon'},
  p:{fr:'Megève, Savoie, France',en:'Megève, Savoie, France'},
  d:{fr:"Un gâteau de pommes de terre râpées, de pruneaux et de lard, cuit quatre heures au bain-marie dans un moule tapissé de bardes. Sucré et salé, il partait au four du village le matin et revenait pour le dîner.",
     en:"A cake of grated potato, prunes and bacon, cooked for four hours in a bain-marie in a mould lined with bacon. Sweet and savoury, it went to the village oven in the morning and came back for supper."},
  i:[['potato',1.5,'kg'],['smoked_bacon',250,'g'],['prunes',200,'g'],['raisins',100,'g'],['egg',4,'pc'],['heavy_cream',250,'ml'],['sugar',60,'g'],['pear',2,'pc'],['nutmeg',1,'tsp'],['cinnamon',1,'tsp'],['butter',60,'g'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Râpez les pommes de terre crues à la grille fine et pressez-les dans un linge : l'eau ruinerait la texture.","Mêlez-les aux œufs, à la crème, au sucre, aux épices, aux pruneaux dénoyautés, aux raisins et aux poires en dés.","Tapissez un moule à charlotte de bardes de lard, en les faisant déborder à l'extérieur.","Remplissez, rabattez les bardes sur le dessus et couvrez d'un papier beurré et d'un couvercle.","Cuisez 4 heures au bain-marie à 150 °C. Laissez tiédir 20 minutes avant de démouler et de trancher."],
     en:["Grate the raw potatoes finely and squeeze them in a cloth: the water would ruin the texture.","Mix with the eggs, cream, sugar, spices, stoned prunes, raisins and diced pears.","Line a charlotte mould with bacon rashers, letting them hang over the sides.","Fill it, fold the rashers over the top and cover with buttered paper and a lid.","Cook for 4 hours in a bain-marie at 150°C. Let it settle for 20 minutes before turning out and slicing."]} },

{ id:'bacalhau-com-natas', c:'eu', lat:38.716, lon:-9.140, base:6, prep:35, cook:40, diff:1, tags:['sea','bake','comfort'],
  art:{v:'plate',bg:'#2c3440',plate:'#f4ecd8',style:'stew',food:['#f4f0e6','#e0b45a','#f0e8d0','#c9a878'],garnish:'#7fae6a'},
  n:{fr:'Bacalhau com natas',en:'Bacalhau com natas'},
  p:{fr:'Lisbonne, Portugal',en:'Lisbon, Portugal'},
  d:{fr:"De la morue effeuillée et des pommes de terre frites en allumettes, liées à la béchamel et à la crème, gratinées au four. Le plat de restaurant le plus commandé du Portugal, dit-on — et sans doute le plus consolant.",
     en:"Flaked salt cod and matchstick fried potatoes bound with béchamel and cream, browned in the oven. Said to be the most ordered restaurant dish in Portugal — and certainly the most consoling."},
  i:[['salt_cod',700,'g'],['potato',1,'kg'],['onion',3,'pc'],['garlic',4,'clove'],['whole_milk',700,'ml'],['heavy_cream',300,'ml'],['butter',80,'g'],['flour',70,'g'],['nutmeg',1,'pinch'],['olive_oil',80,'ml'],['frying_oil',1,'l'],['bay_leaf',2,'pc'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Dessalez la morue 36 heures en changeant l'eau six fois, puis pochez-la 8 minutes dans le lait avec le laurier ; effeuillez-la et gardez le lait.","Taillez les pommes de terre en allumettes et faites-les frire jusqu'à ce qu'elles dorent à peine : elles finiront de cuire au four.","Faites fondre l'oignon et l'ail dans l'huile d'olive, ajoutez la morue effeuillée et laissez-la s'imprégner.","Préparez une béchamel avec le beurre, la farine et le lait parfumé, puis détendez-la à la crème et muscadez.","Mêlez morue, pommes de terre et sauce, versez dans un plat et gratinez 25 minutes à 200 °C."],
     en:["Desalt the cod for 36 hours, changing the water six times, then poach it for 8 minutes in the milk with the bay; flake it and keep the milk.","Cut the potatoes into matchsticks and fry them until barely golden: they will finish cooking in the oven.","Soften the onion and garlic in the olive oil, add the flaked cod and let it take up the flavour.","Make a béchamel with the butter, flour and infused milk, then loosen it with the cream and season with nutmeg.","Combine cod, potatoes and sauce, tip into a dish and bake for 25 minutes at 200°C."]} },

{ id:'carne-vinha-d-alhos', c:'eu', lat:32.650, lon:-16.910, base:6, prep:30, cook:60, diff:2, tags:['pork','festive','slow'],
  art:{v:'pot',bg:'#33251c',plate:'#f0e4c8',style:'stew',food:['#8f3b2a','#c9754a','#e0913a','#f0d8a8'],garnish:'#7fae6a'},
  n:{fr:'Carne de vinha d’alhos',en:'Carne de vinha d’alhos'},
  p:{fr:'Funchal, Madère, Portugal',en:'Funchal, Madeira, Portugal'},
  d:{fr:"Du porc mariné une semaine dans le vin et l'ail, puis frit et servi dans un bolo do caco. Les navigateurs portugais emportèrent cette marinade jusqu'à Goa, où elle devint le vindaloo.",
     en:"Pork marinated for a week in wine and garlic, then fried and served in a bolo do caco. Portuguese navigators carried this marinade as far as Goa, where it became vindaloo."},
  i:[['pork_shoulder',1.2,'kg'],['white_wine',500,'ml'],['white_wine_vinegar',150,'ml'],['garlic',12,'clove'],['bay_leaf',4,'pc'],['piri_piri',2,'tsp'],['thyme',3,'sprig'],['orange',2,'pc'],['lard',80,'g'],['sweet_potato',600,'g'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Taillez le porc en cubes de 4 cm et mettez-les dans une jarre avec le vin, le vinaigre, l'ail écrasé, le laurier, le thym et le piment.","Laissez mariner cinq à sept jours au frais, en remuant chaque jour : la viande doit blanchir et s'attendrir.","Égouttez et épongez soigneusement, puis faites frire les cubes dans le saindoux jusqu'à belle coloration.","Versez un verre de marinade filtrée dans la poêle et laissez réduire à glace, en enrobant la viande.","Servez avec des tranches d'orange, des patates douces rôties et du bolo do caco chaud."],
     en:["Cut the pork into 4 cm cubes and put them in a jar with the wine, vinegar, crushed garlic, bay, thyme and chilli.","Marinate for five to seven days in the cold, stirring daily: the meat should pale and tenderise.","Drain and dry thoroughly, then fry the cubes in lard until well coloured.","Pour a glass of strained marinade into the pan and reduce to a glaze, coating the meat.","Serve with orange slices, roast sweet potato and warm bolo do caco."]} },

{ id:'bolo-de-mel', c:'eu', lat:32.648, lon:-16.914, base:10, prep:60, cook:50, diff:2, tags:['sweet','bake','festive'],
  art:{v:'plate',bg:'#2e2419',plate:'#f4ead4',style:'cake',food:['#6f4a2a','#8f6a4a','#c9924a','#f0e0bc'],garnish:'#c9754a'},
  n:{fr:'Bolo de mel',en:'Madeira honey cake'},
  p:{fr:'Funchal, Madère, Portugal',en:'Funchal, Madeira, Portugal'},
  d:{fr:"Le gâteau de Noël madérien, au miel de canne à sucre et à treize épices, que l'on prépare le 8 décembre et que l'on ne rompt qu'à la main — jamais au couteau. Il se garde un an et gagne à vieillir.",
     en:"The Madeiran Christmas cake, made with cane honey and thirteen spices, prepared on 8 December and broken only by hand — never cut. It keeps for a year and improves with age."},
  i:[['flour',700,'g'],['molasses',500,'g'],['butter',200,'g'],['lard',100,'g'],['sugar',150,'g'],['walnuts',150,'g'],['almonds',150,'g'],['candied_fruit',150,'g'],['cinnamon',2,'tsp'],['cloves',1,'tsp'],['fennel',1,'tsp'],['star_anise',3,'pc'],['dark_rum',100,'ml'],['orange_zest',2,'pc'],['baking_soda',1,'tsp'],['salt',null,'']],
  s:{fr:["Faites chauffer le miel de canne avec le beurre et le saindoux jusqu'à ce que tout soit fondu, puis laissez tiédir.","Écrasez au mortier la cannelle, les clous, le fenouil et l'anis étoilé, et mêlez-les à la farine avec le bicarbonate.","Incorporez le miel tiède, le sucre, le rhum et le zeste, et travaillez la pâte 10 minutes : elle est lourde et collante.","Ajoutez fruits confits, noix et amandes concassées, puis laissez reposer la pâte trois jours au frais, couverte.","Répartissez dans des moules ronds bas et enfournez 50 minutes à 170 °C. Attendez trois semaines avant d'y toucher."],
     en:["Warm the cane honey with the butter and lard until melted, then let it cool a little.","Pound the cinnamon, cloves, fennel and star anise in a mortar and mix them into the flour with the bicarbonate.","Work in the warm honey, sugar, rum and zest, and knead for 10 minutes: the dough is heavy and sticky.","Add the candied fruit, chopped walnuts and almonds, then rest the dough for three days in the cold, covered.","Divide between shallow round tins and bake for 50 minutes at 170°C. Wait three weeks before touching it."]} },

{ id:'arroz-de-tamboril', c:'eu', lat:39.356, lon:-9.381, base:6, prep:30, cook:45, diff:2, tags:['sea','rice','sunday'],
  art:{v:'pot',bg:'#33251c',plate:'#f2e8d0',style:'rice',food:['#c9402c','#e0913a','#f0e4c0','#f4f0e6'],garnish:'#6fbf8f'},
  n:{fr:'Arroz de tamboril',en:'Monkfish rice'},
  p:{fr:'Peniche, Estrémadure, Portugal',en:'Peniche, Estremadura, Portugal'},
  d:{fr:"Un riz de lotte servi coulant dans un plat de terre, avec des crevettes et de la coriandre. Au Portugal le riz de poisson doit être malandrinho — mal élevé, dit-on : il ne doit surtout pas se tenir.",
     en:"A monkfish rice served loose in an earthenware dish, with prawns and coriander. In Portugal a fish rice must be malandrinho — badly behaved, they say: it must on no account hold together."},
  i:[['monkfish',1,'kg'],['shrimp',400,'g'],['long_grain_rice',350,'g'],['onion',2,'pc'],['garlic',6,'clove'],['ripe_tomato',400,'g'],['green_pepper',1,'pc'],['white_wine',200,'ml'],['fish_broth',1.2,'l'],['cilantro',1,'bunch'],['piri_piri',1,'tsp'],['olive_oil',100,'ml'],['bay_leaf',2,'pc'],['salt',null,'']],
  s:{fr:["Faites un fumet avec la tête et l'arête centrale de la lotte, 25 minutes, puis filtrez-le.","Faites un refogado : oignon, ail et poivron fondus lentement dans l'huile, puis tomate râpée jusqu'à réduction.","Versez le vin blanc, laissez évaporer, ajoutez le riz et nacrez-le deux minutes.","Mouillez du fumet bouillant — trois fois le volume de riz, le plat doit rester très humide — et laissez cuire 12 minutes.","Ajoutez la lotte en gros médaillons et les crevettes pour 6 minutes, puis coupez le feu et couvrez de coriandre ciselée."],
     en:["Make a stock with the monkfish head and backbone for 25 minutes, then strain it.","Make a refogado: onion, garlic and pepper softened slowly in oil, then grated tomato cooked down.","Pour in the white wine, let it evaporate, add the rice and toast it for two minutes.","Moisten with boiling stock — three times the volume of rice, the dish must stay very wet — and cook for 12 minutes.","Add the monkfish in large medallions and the prawns for 6 minutes, then cut the heat and cover with chopped coriander."]} },

{ id:'caldeirada-de-enguias', c:'eu', lat:40.744, lon:-8.639, base:6, prep:30, cook:40, diff:2, tags:['sea','stew','slow'],
  art:{v:'pot',bg:'#28331f',plate:'#f0e4c8',style:'fish',food:['#8f6a4a','#e0913a','#7fae5a','#f0e8d0'],garnish:'#6fbf8f'},
  n:{fr:'Caldeirada d’anguilles',en:'Eel caldeirada'},
  p:{fr:'Murtosa, ria d’Aveiro, Portugal',en:'Murtosa, Ria de Aveiro, Portugal'},
  d:{fr:"Les anguilles de la ria d'Aveiro mijotées en couches avec pommes de terre, oignons et poivrons. Les pêcheurs de moliceiros — ces barques à voile qui récoltaient les algues — la cuisaient à bord dans un chaudron de fonte.",
     en:"Eels from the Ria de Aveiro stewed in layers with potatoes, onions and peppers. The moliceiro fishermen — whose sailing boats harvested seaweed — cooked it on board in a cast-iron pot."},
  i:[['eel',1.2,'kg'],['potato',800,'g'],['onion',4,'pc'],['green_pepper',2,'pc'],['ripe_tomato',500,'g'],['garlic',6,'clove'],['white_wine',250,'ml'],['olive_oil',150,'ml'],['sweet_paprika',1,'tbsp'],['piri_piri',1,'tsp'],['bay_leaf',3,'pc'],['cilantro',1,'bunch'],['cornmeal',300,'g'],['salt',null,'']],
  s:{fr:["Faites tronçonner les anguilles en morceaux de 6 cm et laissez-les dégorger 30 minutes au gros sel, puis rincez-les.","Taillez tous les légumes en rondelles régulières de 5 mm.","Montez la marmite en couches : oignon, pomme de terre, poivron, tomate, anguille, en salant et huilant chaque étage.","Répétez, terminez par les légumes, versez le vin blanc et de l'eau à mi-hauteur seulement, ajoutez paprika, piment et laurier.","Laissez mijoter 35 minutes sans remuer — secouez la marmite — et couvrez de coriandre. Servez avec une polenta ferme."],
     en:["Have the eels cut into 6 cm sections and let them draw with coarse salt for 30 minutes, then rinse them.","Cut all the vegetables into even 5 mm rounds.","Build the pot in layers: onion, potato, pepper, tomato, eel, salting and oiling each storey.","Repeat, finish with vegetables, pour in the white wine and water to come only halfway, and add paprika, chilli and bay.","Simmer for 35 minutes without stirring — shake the pot instead — and cover with coriander. Serve with firm polenta."]} },

{ id:'pao-de-lo-de-ovar', c:'eu', lat:40.860, lon:-8.626, base:8, prep:25, cook:35, diff:2, tags:['sweet','bake','festive'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ead4',style:'cake',food:['#e8c46a','#f0e0a8','#c98a2c','#f4f0e6'],garnish:'#c9754a'},
  n:{fr:'Pão de ló d’Ovar',en:'Ovar pão de ló'},
  p:{fr:'Ovar, Beira Litoral, Portugal',en:'Ovar, Beira Litoral, Portugal'},
  d:{fr:"Un gâteau d'œufs volontairement sous-cuit, dont le cœur reste coulant comme une crème. Il se cuit dans un moule tapissé de papier, et l'on juge de sa réussite au tremblement du centre quand on le sort du four.",
     en:"An egg cake deliberately underbaked, its heart left runny as custard. It is baked in a paper-lined mould, and success is judged by the wobble of the centre as it leaves the oven."},
  i:[['egg_yolk',18,'pc'],['egg',6,'pc'],['sugar',300,'g'],['flour',150,'g'],['salt',null,'']],
  s:{fr:["Chemisez un moule rond de papier sulfurisé en le laissant dépasser largement, sans le beurrer.","Fouettez les jaunes, les œufs entiers et le sucre au bain-marie tiède 15 minutes : le mélange doit tripler de volume et blanchir.","Retirez du bain-marie et continuez de fouetter jusqu'à refroidissement complet.","Incorporez la farine tamisée en trois fois, en soulevant la masse à la spatule, sans jamais la casser.","Enfournez 30 à 35 minutes à 180 °C. Le tour doit être pris et le centre encore liquide : sortez-le avant d'être rassuré."],
     en:["Line a round mould with baking paper, letting it overhang generously, without buttering it.","Whisk the yolks, whole eggs and sugar over a warm bain-marie for 15 minutes: the mixture should treble and pale.","Take it off the heat and keep whisking until completely cold.","Fold in the sifted flour in three additions, lifting with a spatula and never knocking out the air.","Bake for 30 to 35 minutes at 180°C. The rim should be set and the centre still liquid: take it out before you feel reassured."]} },

{ id:'sopa-de-peixe-algarvia', c:'eu', lat:37.028, lon:-7.841, base:6, prep:30, cook:45, diff:1, tags:['sea','soup','comfort'],
  art:{v:'bowl',bg:'#33251c',plate:'#f2e8d0',style:'soup',food:['#c9402c','#e0913a','#f0e4c0','#7fae5a'],garnish:'#6fbf8f'},
  n:{fr:'Soupe de poisson algarvienne',en:'Algarve fish soup'},
  p:{fr:'Olhão, Algarve, Portugal',en:'Olhão, Algarve, Portugal'},
  d:{fr:"Une soupe de poissons de roche épaissie de pain, parfumée à la coriandre et au piment. Olhão, port de thoniers et de conserveries, en fait sa soupe du quotidien depuis que la ville existe.",
     en:"A rockfish soup thickened with bread, scented with coriander and chilli. Olhão, a port of tuna boats and canneries, has made it its everyday soup since the town began."},
  i:[['rockfish',1.2,'kg'],['onion',3,'pc'],['garlic',6,'clove'],['ripe_tomato',600,'g'],['green_pepper',2,'pc'],['stale_bread',250,'g'],['olive_oil',120,'ml'],['cilantro',1,'bunch'],['piri_piri',1,'tsp'],['bay_leaf',3,'pc'],['white_wine',200,'ml'],['egg',4,'pc'],['salt',null,'']],
  s:{fr:["Faites cuire les poissons de roche 25 minutes dans deux litres d'eau avec le laurier, puis passez le bouillon au moulin à légumes.","Faites fondre oignon, ail et poivron dans l'huile, ajoutez la tomate râpée et laissez réduire 20 minutes.","Versez le bouillon filtré et le vin blanc, ajoutez le piment et laissez frémir 10 minutes.","Émiettez le pain rassis dans la soupe et laissez-le gonfler avant d'écraser à la cuillère de bois.","Pochez les œufs directement dans la soupe 3 minutes, et couvrez de coriandre ciselée au moment de servir."],
     en:["Cook the rockfish for 25 minutes in two litres of water with the bay, then pass the broth through a food mill.","Soften the onion, garlic and pepper in the oil, add the grated tomato and reduce for 20 minutes.","Pour in the strained broth and white wine, add the chilli and simmer for 10 minutes.","Crumble the stale bread into the soup, let it swell, then crush it with a wooden spoon.","Poach the eggs directly in the soup for 3 minutes, and cover with chopped coriander to serve."]} },

{ id:'xerem-de-conquilhas', c:'eu', lat:37.019, lon:-7.930, base:4, prep:25, cook:45, diff:1, tags:['sea','comfort','slow'],
  art:{v:'pot',bg:'#33301f',plate:'#f0e4c8',style:'stew',food:['#e8c46a','#f2e0a8','#f4f0e6','#7fae5a'],garnish:'#6fbf8f'},
  n:{fr:'Xerém aux coques',en:'Xerém with cockles'},
  p:{fr:'Faro, Algarve, Portugal',en:'Faro, Algarve, Portugal'},
  d:{fr:"Une bouillie de maïs concassé de l'Algarve, couronnée de coques ouvertes dans leur jus. Cousine de la polenta et du grits américain, elle porte un nom d'origine arabe, comme tant de choses dans le Sud portugais.",
     en:"A porridge of cracked maize from the Algarve, crowned with cockles opened in their own juice. Cousin to polenta and American grits, it bears an Arabic-derived name, like so much in the Portuguese south."},
  i:[['cracked_corn',300,'g'],['clams',1.5,'kg'],['smoked_bacon',150,'g'],['chorizo',100,'g'],['onion',2,'pc'],['garlic',6,'clove'],['ripe_tomato',300,'g'],['cilantro',1,'bunch'],['white_wine',150,'ml'],['olive_oil',100,'ml'],['piri_piri',1,'tsp'],['bay_leaf',2,'pc'],['salt',null,'']],
  s:{fr:["Faites dégorger les coques deux heures dans de l'eau salée pour qu'elles rendent leur sable.","Faites revenir lard et chorizo, ajoutez oignon, ail et tomate, et laissez compoter 15 minutes.","Ouvrez les coques à part avec le vin blanc, 3 minutes à couvert, puis filtrez soigneusement leur jus.","Versez un litre et demi d'eau et le jus des coques sur le refogado, portez à ébullition, puis versez le maïs concassé en pluie.","Remuez 35 minutes à feu doux jusqu'à épaississement, puis ajoutez les coques et beaucoup de coriandre hors du feu."],
     en:["Purge the cockles for two hours in salted water so they release their sand.","Fry the bacon and chorizo, add the onion, garlic and tomato, and stew for 15 minutes.","Open the cockles separately with the white wine, 3 minutes covered, then strain their liquor carefully.","Pour a litre and a half of water and the cockle liquor over the refogado, bring to the boil, then rain in the cracked maize.","Stir for 35 minutes over low heat until thick, then add the cockles and plenty of coriander off the heat."]} },

{ id:'ensopado-de-borrego', c:'eu', lat:38.802, lon:-7.457, base:6, prep:30, cook:100, diff:1, tags:['lamb','slow','comfort'],
  art:{v:'pot',bg:'#2b2419',plate:'#f0e4c8',style:'stew',food:['#8f5a3a','#c9754a','#e8dcb8','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Ensopado de borrego',en:'Lamb ensopado'},
  p:{fr:'Borba, Alentejo, Portugal',en:'Borba, Alentejo, Portugal'},
  d:{fr:"Un ragoût d'agneau servi sur des tranches de pain qui boivent le bouillon au fond de l'assiette. Ensopado veut dire « trempé » : le pain n'est pas un accompagnement, c'est la moitié du plat.",
     en:"A lamb stew served over slices of bread that soak up the broth at the bottom of the plate. Ensopado means 'soaked': the bread is not a side dish, it is half the dish."},
  i:[['lamb_shoulder',1.5,'kg'],['onion',3,'pc'],['garlic',8,'clove'],['ripe_tomato',400,'g'],['white_wine',300,'ml'],['bay_leaf',3,'pc'],['mint',1,'bunch'],['sweet_paprika',1,'tbsp'],['olive_oil',120,'ml'],['potato',600,'g'],['rustic_bread',8,'slice'],['piri_piri',1,'tsp'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites mariner l'agneau en gros morceaux 4 heures dans le vin blanc, l'ail écrasé, le paprika et le laurier.","Égouttez, épongez et saisissez la viande dans l'huile d'olive jusqu'à belle coloration.","Ajoutez l'oignon émincé et la tomate râpée, laissez compoter, puis versez la marinade filtrée.","Couvrez d'eau à hauteur et laissez mijoter 1 h 15 ; ajoutez les pommes de terre pour les 25 dernières minutes.","Tapissez le fond des assiettes creuses de tranches de pain, versez le ragoût brûlant dessus et couvrez de menthe fraîche."],
     en:["Marinate the lamb in large pieces for 4 hours in the white wine, crushed garlic, paprika and bay.","Drain, dry and sear the meat in olive oil until well coloured.","Add the sliced onion and grated tomato, let them cook down, then pour in the strained marinade.","Cover with water and simmer for 1¼ hours; add the potatoes for the last 25 minutes.","Line deep plates with slices of bread, pour the scalding stew over them and cover with fresh mint."]} },

{ id:'sericaia', c:'eu', lat:38.881, lon:-7.163, base:6, prep:25, cook:25, diff:2, tags:['sweet','bake','fruit'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ead4',style:'cake',food:['#e8c46a','#8f6a4a','#f0e0bc','#c9924a'],garnish:'#c9754a'},
  n:{fr:'Sericaia',en:'Sericaia'},
  p:{fr:'Elvas, Alentejo, Portugal',en:'Elvas, Alentejo, Portugal'},
  d:{fr:"Un entremets aux œufs et à la cannelle, cuit à feu vif dans un plat de terre où il se fendille en crevasses. Il se sert avec les prunes d'Elvas confites, et son nom viendrait de Sérica — la Chine des Anciens.",
     en:"An egg and cinnamon pudding, baked fiercely in an earthenware dish where it cracks into fissures. Served with candied Elvas plums, and its name is said to come from Serica — the ancients' name for China."},
  i:[['whole_milk',500,'ml'],['egg',6,'pc'],['egg_yolk',3,'pc'],['sugar',250,'g'],['flour',60,'g'],['cinnamon',2,'tbsp'],['lemon_zest',2,'pc'],['prunes',300,'g'],['salt',null,'']],
  s:{fr:["Faites infuser le lait avec le zeste de citron et un bâton de cannelle, puis filtrez.","Délayez la farine dans un peu de lait froid, puis versez le lait chaud en fouettant et faites épaissir 5 minutes.","Fouettez les jaunes et le sucre au ruban, incorporez la crème tiède, puis les blancs montés en neige.","Versez à la louche dans un plat de terre, en laissant chaque louchée former une vague, et poudrez généreusement de cannelle entre chacune.","Enfournez 25 minutes à 220 °C : la surface doit se craqueler profondément. Servez tiède avec les prunes."],
     en:["Infuse the milk with the lemon zest and a cinnamon stick, then strain it.","Slake the flour in a little cold milk, then pour in the hot milk while whisking and thicken for 5 minutes.","Whisk the yolks and sugar to the ribbon, fold in the warm cream, then the whites beaten to peaks.","Ladle into an earthenware dish, letting each ladleful form a wave, and dust generously with cinnamon between each.","Bake for 25 minutes at 220°C: the surface should crack deeply. Serve warm with the plums."]} },

{ id:'empadas-de-vila-vicosa', c:'eu', lat:38.774, lon:-7.415, base:8, prep:60, cook:35, diff:2, tags:['poultry','bake','street'],
  art:{v:'board',bg:'#33291f',plate:'#f2e6c8',style:'pastry',food:['#e0b45a','#f2dfa8','#c98a2c','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Empadas de Vila Viçosa',en:'Vila Viçosa empadas'},
  p:{fr:'Vila Viçosa, Alentejo, Portugal',en:'Vila Viçosa, Alentejo, Portugal'},
  d:{fr:"De petites tourtes de poule à la pâte au saindoux, moulées dans des godets de fer-blanc. On les vendait à la sortie de la messe et sur le parvis des sanctuaires, tièdes, enveloppées dans du papier.",
     en:"Small chicken pies in lard pastry, moulded in tin cups. They were sold outside mass and on the forecourts of shrines, warm, wrapped in paper."},
  i:[['flour',500,'g'],['lard',200,'g'],['warm_water',180,'ml'],['egg',3,'pc'],['chicken',1,'kg'],['onion',2,'pc'],['garlic',4,'clove'],['bay_leaf',2,'pc'],['white_wine',150,'ml'],['nutmeg',1,'pinch'],['lemon',1,'pc'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Pochez la poule 1 heure avec oignon, ail, laurier et vin blanc ; laissez-la tiédir dans son bouillon.","Désossez-la et hachez la chair au couteau, en petits morceaux ; mêlez-la à un peu de bouillon réduit, à la muscade et au citron.","Pétrissez la farine, le saindoux fondu, l'eau tiède et le sel en une pâte souple ; laissez-la reposer 30 minutes.","Foncez de petits moules cylindriques, garnissez de farce et couvrez d'un disque de pâte soudé au pouce.","Dorez à l'œuf, percez une cheminée et enfournez 35 minutes à 190 °C."],
     en:["Poach the hen for 1 hour with onion, garlic, bay and white wine; let it cool in its broth.","Bone it and chop the meat by knife into small pieces; mix with a little reduced broth, the nutmeg and lemon.","Knead the flour, melted lard, warm water and salt into a supple dough; rest it for 30 minutes.","Line small cylindrical moulds, fill with the mixture and cover with a disc of dough sealed with your thumb.","Glaze with egg, cut a vent and bake for 35 minutes at 190°C."]} },

{ id:'folar-de-chaves', c:'eu', lat:41.607, lon:-7.313, base:10, prep:120, cook:45, diff:2, tags:['pork','bake','festive'],
  art:{v:'board',bg:'#2f2519',plate:'#f2e6c8',style:'roll',food:['#e0b45a','#8f5a3a','#f2dfa8','#c98a2c'],garnish:'#7fae6a'},
  n:{fr:'Folar de viande',en:'Meat folar'},
  p:{fr:'Valpaços, Trás-os-Montes, Portugal',en:'Valpaços, Trás-os-Montes, Portugal'},
  d:{fr:"Un pain brioché fourré de quatre charcuteries fumées, cuit à Pâques dans les fours communaux. Le folar se distribuait aux filleuls le dimanche de Pâques, en échange des violettes offertes le dimanche des Rameaux.",
     en:"A brioche loaf stuffed with four smoked meats, baked at Easter in the communal ovens. The folar was given to godchildren on Easter Sunday, in exchange for the violets offered on Palm Sunday."},
  i:[['flour',800,'g'],['whole_milk',250,'ml'],['fresh_yeast',30,'g'],['egg',4,'pc'],['olive_oil',120,'ml'],['smoked_bacon',200,'g'],['chorizo',200,'g'],['alheira_sausage',200,'g'],['smoked_pork_collar',200,'g'],['sweet_paprika',1,'tsp'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Délayez la levure dans le lait tiède, puis pétrissez avec la farine, les œufs, l'huile et le sel pendant 15 minutes.","Laissez lever 1 h 30 : la pâte doit doubler et rester souple, presque collante.","Détaillez toutes les charcuteries en dés de 1 cm et faites-les revenir brièvement pour qu'elles rendent un peu de gras.","Étalez la pâte, parsemez de charcuterie et de paprika, roulez, puis enroulez le boudin en couronne dans un plat rond.","Laissez pousser 45 minutes, dorez à l'œuf et enfournez 45 minutes à 180 °C."],
     en:["Dissolve the yeast in the warm milk, then knead with the flour, eggs, oil and salt for 15 minutes.","Prove for 1½ hours: the dough should double and stay supple, almost sticky.","Cut all the cured meats into 1 cm dice and fry them briefly so they release a little fat.","Roll out the dough, scatter over the meats and paprika, roll it up, then coil the log into a ring in a round tin.","Prove for 45 minutes, glaze with egg and bake for 45 minutes at 180°C."]} },

{ id:'cabrito-a-serrana', c:'eu', lat:41.806, lon:-6.757, base:6, prep:30, cook:150, diff:2, tags:['lamb','sunday','slow'],
  art:{v:'board',bg:'#2b2419',plate:'#f0e4c8',style:'grill',food:['#8f5a3a','#c9754a','#e8d8b8','#e0b45a'],garnish:'#7fae6a'},
  n:{fr:'Chevreau à la mode de la serra',en:'Serra-style roast kid'},
  p:{fr:'Bragance, Trás-os-Montes, Portugal',en:'Bragança, Trás-os-Montes, Portugal'},
  d:{fr:"Un chevreau de lait rôti au four à bois avec du riz cuit dans son jus, plat de Noël et de Pâques du Nord-Est portugais. La marinade au vin rouge et au paprika lui donne sa robe presque noire.",
     en:"A milk-fed kid roasted in a wood oven with rice cooked in its juices, the Christmas and Easter dish of Portugal's north-east. A marinade of red wine and paprika gives it its near-black crust."},
  i:[['goat_meat',2,'kg'],['red_wine',400,'ml'],['garlic',10,'clove'],['sweet_paprika',2,'tbsp'],['bay_leaf',4,'pc'],['lard',100,'g'],['olive_oil',100,'ml'],['long_grain_rice',300,'g'],['onion',2,'pc'],['potato',800,'g'],['piri_piri',1,'tsp'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites mariner le chevreau 12 heures dans le vin rouge, l'ail écrasé, le paprika, le piment et le laurier.","Frottez la viande de saindoux, posez-la sur un lit d'oignons dans un plat de terre et arrosez de la marinade.","Enfournez 1 h 30 à 170 °C en arrosant toutes les 20 minutes, puis ajoutez les pommes de terre en quartiers.","Prélevez deux louches de jus, mouillez-en le riz cru dans un plat à part avec de l'eau, et enfournez-le à côté 25 minutes.","Montez à 220 °C dix minutes pour dorer la viande. Servez le chevreau et le riz ensemble."],
     en:["Marinate the kid for 12 hours in the red wine, crushed garlic, paprika, chilli and bay.","Rub the meat with lard, set it on a bed of onions in an earthenware dish and pour over the marinade.","Roast for 1½ hours at 170°C, basting every 20 minutes, then add the quartered potatoes.","Take two ladles of the juices, use them to moisten the raw rice in a separate dish with water, and bake it alongside for 25 minutes.","Raise to 220°C for ten minutes to brown the meat. Serve the kid and rice together."]} },

{ id:'pica-pau', c:'eu', lat:39.744, lon:-8.807, base:4, prep:20, cook:25, diff:1, tags:['beef','fast','street'],
  art:{v:'plate',bg:'#33251c',plate:'#f0e4c8',style:'stew',food:['#8f5a3a','#c9754a','#7fae5a','#e8dcb8'],garnish:'#7fae6a'},
  n:{fr:'Pica-pau',en:'Pica-pau'},
  p:{fr:'Leiria, Beira Litoral, Portugal',en:'Leiria, Beira Litoral, Portugal'},
  d:{fr:"Des dés de bœuf sautés au vin blanc et à la moutarde, servis brûlants avec des cornichons et des olives, que l'on pique à la fourchette au centre de la table. Le nom veut dire « pivert » : on picore.",
     en:"Cubes of beef sautéed with white wine and mustard, served scalding with gherkins and olives, speared with forks from a dish in the middle of the table. The name means 'woodpecker': you peck at it."},
  i:[['beef_sirloin',700,'g'],['garlic',6,'clove'],['white_wine',200,'ml'],['dijon_mustard',2,'tbsp'],['butter',60,'g'],['olive_oil',60,'ml'],['pickles',150,'g'],['green_olives',150,'g'],['piri_piri',1,'tsp'],['bay_leaf',2,'pc'],['parsley',5,'tbsp'],['rustic_bread',1,'pc'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Taillez le bœuf en dés de 2 cm et salez-les au dernier moment seulement.","Faites chauffer l'huile et le beurre jusqu'à ce qu'ils mousse, puis saisissez la viande à feu très vif, par petites quantités.","Ajoutez l'ail écrasé, le laurier et le piment, et laissez parfumer 30 secondes sans brûler l'ail.","Déglacez au vin blanc, ajoutez la moutarde et laissez réduire 3 minutes : la sauce doit rester courte et brillante.","Versez dans un plat creux avec cornichons et olives, couvrez de persil et servez avec du pain pour saucer."],
     en:["Cut the beef into 2 cm cubes and salt them only at the last moment.","Heat the oil and butter until foaming, then sear the meat over very high heat, in small batches.","Add the crushed garlic, bay and chilli, and let them perfume the pan for 30 seconds without burning the garlic.","Deglaze with white wine, add the mustard and reduce for 3 minutes: the sauce should stay short and glossy.","Tip into a deep dish with the gherkins and olives, cover with parsley and serve with bread for mopping."]} },

{ id:'travesseiros-de-colares', c:'eu', lat:38.799, lon:-9.447, base:10, prep:90, cook:20, diff:3, tags:['sweet','bake','festive'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'pastry',food:['#f2dfa8','#e0b45a','#f4f0e6','#c98a2c'],garnish:'#c9754a'},
  n:{fr:'Travesseiros',en:'Travesseiros'},
  p:{fr:'Colares, Sintra, Portugal',en:'Colares, Sintra, Portugal'},
  d:{fr:"Des « oreillers » de pâte feuilletée garnis d'une crème d'amandes et d'œufs, roulés dans le sucre à la sortie du four. La file d'attente devant la pâtisserie de Sintra qui les a créés ne désemplit pas depuis 1943.",
     en:"'Pillows' of puff pastry filled with an almond and egg cream, rolled in sugar as they leave the oven. The queue outside the Sintra pastry shop that created them has not thinned since 1943."},
  i:[['flour',400,'g'],['butter',300,'g'],['ice_water',180,'ml'],['almonds',250,'g'],['sugar',350,'g'],['egg',4,'pc'],['egg_yolk',4,'pc'],['water',120,'ml'],['lemon_zest',1,'pc'],['salt',null,'']],
  s:{fr:["Préparez un feuilletage : détrempe de farine, eau glacée et sel, puis trois tours simples avec le beurre, en reposant 30 minutes entre chacun.","Cuisez le sucre et l'eau en sirop au petit boulé avec le zeste, puis retirez du feu.","Incorporez la poudre d'amandes, laissez tiédir, puis ajoutez les œufs et les jaunes hors du feu.","Faites épaissir cette crème à feu très doux en remuant sans arrêt, puis laissez-la refroidir complètement.","Découpez des rectangles de pâte, déposez la crème en boudin, repliez en oreiller et soudez. Enfournez 20 minutes à 200 °C et roulez dans le sucre encore chauds."],
     en:["Make a puff pastry: a base of flour, iced water and salt, then three single turns with the butter, resting 30 minutes between each.","Cook the sugar and water to soft ball with the zest, then take off the heat.","Stir in the ground almonds, let it cool a little, then add the eggs and yolks off the heat.","Thicken this cream over very low heat, stirring constantly, then cool it completely.","Cut rectangles of pastry, pipe the cream along them, fold into pillows and seal. Bake for 20 minutes at 200°C and roll in sugar while still hot."]} }
];
